	[$'[simulation] sudo -u postgres psql: CREATE ROLE %s LOGIN; GRANT machincast_player TO %s WITH INHERIT FALSE, SET TRUE']=$'[simulation] sudo -u postgres psql : CREATE ROLE %s LOGIN; GRANT machincast_player TO %s WITH INHERIT FALSE, SET TRUE'
	[$'[simulation] sudo -u postgres psql: CREATE ROLE %s NOLOGIN, if they do not exist']=$'[simulation] sudo -u postgres psql : CREATE ROLE %s NOLOGIN, s\'ils n\'existent pas'
	[$'[simulation] sudo -u postgres psql: DROP ROLE IF EXISTS "%s"']=$'[simulation] sudo -u postgres psql : DROP ROLE IF EXISTS "%s"'
	[$'[simulation] sudo -u postgres psql: DROP ROLE IF EXISTS %s']=$'[simulation] sudo -u postgres psql : DROP ROLE IF EXISTS %s'
	[$'[simulation] sudo -u postgres psql: GRANT machincast_player, machincast_indexer, machincast_interface, machincast_intranet TO %s WITH INHERIT FALSE, SET TRUE']=$'[simulation] sudo -u postgres psql : GRANT machincast_player, machincast_indexer, machincast_interface, machincast_intranet TO %s WITH INHERIT FALSE, SET TRUE'
